import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"3.4.18 View Workspace Members","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-18-view-workspace-members/spec.md","filePath":"feature/agency-workspace/3-4-18-view-workspace-members/spec.md"}'),s={name:"feature/agency-workspace/3-4-18-view-workspace-members/spec.md"};function i(n,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_3-4-18-view-workspace-members" tabindex="-1">3.4.18 View Workspace Members <a class="header-anchor" href="#_3-4-18-view-workspace-members" aria-label="Permalink to &quot;3.4.18 View Workspace Members&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.18</td></tr><tr><td>Feature</td><td>View Workspace Members</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>MANAGER / CREATOR / CLIENT</td></tr><tr><td>Version</td><td>3.0 — 2026-10-02 — split into two independent screens, see V2 note</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><p>&gt; V2 (2026-10-02): the single <code>/workspaces/:id/members</code> screen previously listed MANAGER/CREATOR/CLIENT together with a tab switcher. It is now two fully independent routes sharing the same backend list (<code>GET /api/v1/workspaces/{id}/members</code>, unchanged — still returns every role): <code>/workspaces/:id/members</code> (internal staff — MANAGER/CREATOR only, filtered client-side) and <code>/workspaces/:id/clients</code> (CLIENT collaborators only, with its own &quot;Add client&quot; entry point — see FR 3.4.7 V2). This spec is written for the internal Members screen; CLIENT-specific behavior (the Client list, invite lookup) lives in FR 3.4.7.</p><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a Workspace member opens the Members screen (internal staff) or the Clients screen (CLIENT collaborators) of a Workspace.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Workspace members with role MANAGER or CREATOR see the Members screen; Owner/Manager also see the separate Clients screen to manage CLIENT collaborators.</li><li><strong>Purpose:</strong> Shows who takes part in the Workspace and the role each member holds — internal staff and collaborating clients are kept in two separate lists so each audience sees only what&#39;s relevant to them.</li><li><strong>Interface:</strong> Members screen at <code>/workspaces/:id/members</code>, listing MANAGER/CREATOR members with their roles. A separate Clients screen at <code>/workspaces/:id/clients</code> lists active CLIENT members (see FR 3.3.3/3.4.7 for its full behavior).</li><li><strong>Data Processing:</strong> The system loads the Workspace, confirms the caller is an active member of that same Workspace, then lists every active member of the Workspace together with the display name and email of each member&#39;s user or client profile. Both screens call the same <code>GET /api/v1/workspaces/{id}/members</code> endpoint and filter by role client-side (<code>role !== &quot;CLIENT&quot;</code> for Members, <code>role === &quot;CLIENT&quot;</code> for Clients) — the backend does not distinguish the two screens.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Workspace Members Screen (<code>/workspaces/:id/members</code>):</p><ul><li>A table of MANAGER/CREATOR members with name, email, role, and the date each member joined.</li><li>Role badges for MANAGER and CREATOR only — CLIENT rows are filtered out here.</li><li>Active members only; members who have left or were removed do not appear.</li></ul><p>Figure — Workspace Clients Screen (<code>/workspaces/:id/clients</code>, see FR 3.3.3/3.4.7):</p><ul><li>A table of active CLIENT members — display name (from the linked Client Profile) and join date.</li><li>&quot;Add client&quot; action (Owner/Manager only) opens the Gmail-based invite dialog with the auto-suggest hint described in FR 3.4.7 V2.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> The Workspace record; the caller&#39;s active membership row; the Workspace&#39;s active membership rows; the user records and client profiles those memberships reference.</li><li><strong>Output:</strong> The list of members — id, workspaceId, userId, fullName, email, clientProfileId, role, joinedAt, isActive. Role is one of MANAGER, CREATOR, CLIENT — there is no OWNER at Workspace level, since OWNER exists only at Agency level.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-29:</strong> Multi-tenancy — the Workspace must exist and carries its own workspaceId scope, checked before the member list is read; otherwise 404 <code>WORKSPACE_NOT_FOUND</code>. A caller with no active membership in that Workspace cannot read it regardless of system role (except ADMIN).</li><li><strong>BR-30:</strong> The caller must be an active member of the very Workspace being viewed, verified explicitly for the requested Workspace; a caller who is not an active member → 403 <code>WORKSPACE_ACCESS_DENIED</code>. This is the same re-check that immediately cuts off access once a member is removed or leaves.</li><li><strong>BR-31:</strong> The role list at Workspace level is MANAGER, CREATOR, CLIENT; OWNER is not a Workspace role (OWNER exists only at Agency level). The backend list endpoint always returns all three roles together — the Members/Clients screen split (V2) is a presentation-layer filter, not a backend distinction.</li><li><strong>BR-35:</strong> Role/permission checks re-read the caller&#39;s role from the DB at request time via <code>@RequireRoleAspect</code>; <code>SystemRole.ADMIN</code> bypasses the membership check.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>The Workspace must exist; otherwise 404 <code>WORKSPACE_NOT_FOUND</code>, toast MSG38.</li><li>The caller must hold an active membership in that Workspace; otherwise 403 <code>WORKSPACE_ACCESS_DENIED</code>, toast MSG40.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>Member opens <code>/workspaces/:id/members</code>.</li><li>System loads the Workspace; if it does not exist the request fails with 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>System confirms the caller holds an active membership in that Workspace; otherwise the request fails with 403 <code>WORKSPACE_ACCESS_DENIED</code>.</li><li>System reads the Workspace&#39;s active membership rows and resolves the display name and email of each member from the referenced user record or client profile.</li><li>Screen renders the member table with each member&#39;s role and join date.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>2.a1: Workspace does not exist (BR-29) → 404 <code>WORKSPACE_NOT_FOUND</code>, toast MSG38. 2.a2: The member returns to the Workspace list.</li><li>3.a1: Caller is not an active member of that Workspace (BR-30) → 403 <code>WORKSPACE_ACCESS_DENIED</code>, toast MSG40. 3.a2: The member returns to the Workspace list; the Workspace they tried to view does not appear.</li><li>4.a1: A member has no linked user account but is attached through a client profile → the client profile&#39;s display name is shown and the email is empty. 4.a2: The row renders normally with the remaining columns unaffected.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>No data is changed; the Workspace members are displayed.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>None.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',30)])])}const u=t(s,[["render",i]]);export{p as __pageData,u as default};
